package io.zipcoder.originwar.engine;
import io.zipcoder.originwar.model.*;
import io.zipcoder.originwar.campaign.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class SurvivalRulesTest{
 static GameState room(){var s=new GameState();s.width=12;s.height=10;s.playerX=2;s.playerY=2;s.facing=1;s.switchX=8;s.switchY=7;s.hatchX=9;s.hatchY=8;s.terminalX=3;s.terminalY=3;s.tiles=new Tile[12][10];s.visible=new boolean[12][10];s.explored=new boolean[12][10];s.light=new float[12][10];s.circuits=new int[12][10];for(int x=0;x<12;x++)for(int y=0;y<10;y++){s.tiles[x][y]=x==0||y==0||x==11||y==9?Tile.WALL:Tile.FLOOR;s.explored[x][y]=true;}s.tiles[8][7]=Tile.SWITCH;s.tiles[9][8]=Tile.HATCH;s.tiles[3][3]=Tile.TERMINAL;Arrays.fill(s.routeCosts,100);s.combatRng=12345;s.medicineRng=54;MedicineRules.initialize(s);var gun=add(s,GameState.ItemType.PISTOL,"gun",1);s.flags.add("equipped-weapon:"+gun.id);Visibility.refresh(s);return s;}
 static GameState.Item add(GameState s,GameState.ItemType type,String id,int power){var i=new GameState.Item();i.id=id;i.name=type==GameState.ItemType.MEDICINE?RunContent.medicineFor(s,"heal"):id;i.type=type;i.power=power;s.inventory.add(i);return i;}
 @Test void starterIsPhysicalStatlessAndFinite(){var s=new RunEngine(1).saveState();assertEquals(360,s.reserve);assertEquals(12,s.batteries);assertEquals(7,EquipmentRules.bulk(s));assertEquals(1,s.inventory.stream().filter(i->i.type==GameState.ItemType.PISTOL).count());for(String name:List.of("xp","level","str","intel","dex","attributePoints","aliceTrust"))assertThrows(NoSuchFieldException.class,()->GameState.class.getField(name));RunEngine.validateState(s);}
 @Test void inspectionDoesNotAdvanceOrConsumeRandomness(){var run=new RunEngine(room());var before=run.saveState();var r=run.submit(PlayerAction.of(PlayerAction.Type.SCAN));assertTrue(r.accepted());assertFalse(r.stateChanged());assertEquals(before.tick,run.saveState().tick);assertEquals(before.combatRng,run.saveState().combatRng);assertEquals(before.revision,run.saveState().revision);}
 @Test void forecastAndSnapshotsArePure(){var run=new RunEngine(room());var before=run.saveState();for(int i=0;i<30;i++)run.forecast(PlayerAction.move(1,0));var copy=run.snapshot().world();copy.hp=1;copy.circuitPower[0]=false;assertEquals(100,run.saveState().hp);assertEquals(before.combatRng,run.saveState().combatRng);assertTrue(run.saveState().circuitPower[0]);}
 @Test void carefulSlowCrossingUsesThreeTicksAndFinalContact(){var s=room();s.tiles[3][2]=Tile.NO_GRAV;var run=new RunEngine(s);var action=PlayerAction.at(PlayerAction.Type.CAREFUL_MOVE,1,0);assertEquals(3,run.forecast(action).ticks());var r=run.submit(action);assertEquals(3,r.cost());assertEquals(3,run.saveState().playerX);var step=r.events().stream().filter(e->e.type().equals("step")).findFirst().orElseThrow();assertEquals(2,step.fromX());assertEquals(3,step.tick());assertEquals(357,run.saveState().reserve);}
 @Test void rejectedMoveNeverBecomesMelee(){var s=room();s.actors.add(EnemyTurns.actor(GameState.ActorKind.SIRS,"block",3,2));var run=new RunEngine(s);var before=run.saveState();assertFalse(run.submit(PlayerAction.move(1,0)).accepted());assertEquals(before.combatRng,run.saveState().combatRng);assertEquals(0,run.saveState().tick);assertEquals(14,run.saveState().actors.getFirst().hp);}
 @Test void partialOxygenTransferKeepsRemainingContents(){var s=room();s.reserve=300;add(s,GameState.ItemType.OXYGEN,"o2",180);var run=new RunEngine(s);assertTrue(run.submit(PlayerAction.item(PlayerAction.Type.USE,"o2")).accepted());var after=run.saveState();assertEquals(359,after.reserve);assertEquals(120,after.inventory.stream().filter(i->i.id.equals("o2")).findFirst().orElseThrow().power);}
 @Test void batteryPacksCannotLaunderAmmunition(){var s=room();s.batteries=10;add(s,GameState.ItemType.CELL,"cells",12);var run=new RunEngine(s);assertTrue(run.submit(PlayerAction.item(PlayerAction.Type.USE,"cells")).accepted());assertEquals(12,run.saveState().batteries);assertEquals(10,run.saveState().inventory.getLast().power);assertFalse(run.submit(PlayerAction.item(PlayerAction.Type.USE,"cells")).accepted());}
 @Test void duplicatesUseActualBulk(){var s=room();for(int i=0;i<3;i++)add(s,GameState.ItemType.OXYGEN,"tank"+i,180);assertEquals(11,EquipmentRules.bulk(s));var i=new GameState.Item();i.id="rifle";i.type=GameState.ItemType.RIFLE;i.name="rifle";i.x=2;i.y=2;s.floorItems.add(i);var run=new RunEngine(s);assertFalse(run.forecast(PlayerAction.item(PlayerAction.Type.EQUIP,"rifle")).available());assertFalse(run.submit(PlayerAction.item(PlayerAction.Type.PICKUP,"rifle")).accepted());assertEquals(11,EquipmentRules.bulk(run.saveState()));}
 @Test void droppingLastGunLeavesOfficerUnarmed(){var s=room();var run=new RunEngine(s);assertTrue(run.submit(PlayerAction.item(PlayerAction.Type.DROP,"gun")).accepted());var a=run.saveState();assertEquals("unarmed",a.weapon);assertTrue(a.inventory.isEmpty());assertEquals(1,a.floorItems.size());assertFalse(run.submit(PlayerAction.at(PlayerAction.Type.SHOOT,4,2)).accepted());}
 @Test void armorExchangeLeavesOldPhysicalShellOnFloor(){var s=room();var heavy=add(s,GameState.ItemType.ARMOR_HEAVY,"heavy",1);s.flags.add("equipped-armor:"+heavy.id);s.armor="heavy";add(s,GameState.ItemType.ARMOR_LIGHT,"light",1);for(int n=0;n<6;n++)add(s,GameState.ItemType.CELL,"cell"+n,12);assertEquals(12,EquipmentRules.bulk(s));var run=new RunEngine(s);assertTrue(run.submit(PlayerAction.item(PlayerAction.Type.EQUIP,"light")).accepted());var a=run.saveState();assertEquals("light",a.armor);assertEquals(8,EquipmentRules.bulk(a));assertEquals("heavy",a.floorItems.getFirst().id);}
 @Test void braceConservesPhysicalIdentity(){var s=room();s.tiles[3][2]=Tile.DOOR_CLOSED;add(s,GameState.ItemType.DOOR_BRACE,"brace",1);var run=new RunEngine(s);var act=PlayerAction.at(PlayerAction.Type.BRACE,3,2);assertTrue(run.submit(act).accepted());assertTrue(StationSystems.braced(run.saveState(),3,2));assertTrue(run.submit(act).accepted());assertFalse(StationSystems.braced(run.saveState(),3,2));assertEquals(1,run.saveState().inventory.stream().filter(i->i.id.equals("brace")).count());}
 @Test void darknessAndFacingHaveMechanicalMeaning(){var s=room();s.lampOn=false;var a=EnemyTurns.actor(GameState.ActorKind.SIRS,"sensor",7,2);a.facing=3;s.actors.add(a);Visibility.refresh(s);assertFalse(StationSystems.seesPlayer(s,a));s.fixtures.add(new GameState.Fixture("light",2,2,0));Visibility.refresh(s);assertTrue(StationSystems.seesPlayer(s,a));a.facing=1;assertFalse(StationSystems.seesPlayer(s,a));a.facing=3;s.tiles[4][2]=Tile.WALL;assertFalse(StationSystems.seesPlayer(s,a));}
 @Test void closedDoorsAttenuateAndSealedDoorsBlockHearing(){var s=room();for(int y=1;y<9;y++)s.tiles[4][y]=Tile.WALL;s.tiles[4][2]=Tile.DOOR_CLOSED;assertTrue(StationSystems.soundField(s,2,2,10)[6][2]>4);s.tiles[4][2]=Tile.LOCKED_DOOR;assertEquals(Integer.MAX_VALUE,StationSystems.soundField(s,2,2,30)[6][2]);}
 @Test void investigatingMachineRemembersSoundOriginNotHiddenPlayer(){var s=room();s.lampOn=false;var a=EnemyTurns.actor(GameState.ActorKind.SIRS,"listener",8,6);a.facing=1;s.actors.add(a);StationSystems.noise(s,6,6,5,"test",true,new ArrayList<>());s.playerX=2;s.playerY=2;for(int i=0;i<4;i++){s.tick++;s.actionSerial++;EnemyTurns.advance(s,new ArrayList<>());}assertEquals(6,a.lastX);assertEquals(6,a.lastY);assertNotEquals(GameState.Awareness.PURSUE,a.awareness);}
 @Test void patrolMovesWithoutGlobalParityDeadlock(){var s=room();s.lampOn=false;var a=EnemyTurns.actor(GameState.ActorKind.SIRS,"patrol",7,6);a.facing=1;s.actors.add(a);for(int i=0;i<8;i++){s.tick++;s.actionSerial++;EnemyTurns.advance(s,new ArrayList<>());}assertTrue(a.x!=7||a.y!=6||a.facing!=1);}
 @Test void newlyArmedFuseCannotExpireWithinSameCommitment(){var s=room();s.actors.add(EnemyTurns.actor(GameState.ActorKind.ROVER,"rover",3,2));var run=new RunEngine(s);assertTrue(run.submit(PlayerAction.at(PlayerAction.Type.CAREFUL_MOVE,0,1)).accepted());assertEquals(2,run.saveState().actors.getFirst().fuse);assertEquals(100,run.saveState().hp);run.submit(PlayerAction.of(PlayerAction.Type.WAIT));assertEquals(1,run.saveState().actors.getFirst().fuse);run.submit(PlayerAction.of(PlayerAction.Type.WAIT));assertTrue(run.saveState().actors.getFirst().dead);}
 @Test void localPowerDoesNotUnlockHatchOrDisableMobileMachines(){var s=room();s.playerX=3;s.playerY=2;var a=EnemyTurns.actor(GameState.ActorKind.ADD,"mobile",8,6);s.actors.add(a);var run=new RunEngine(s);assertTrue(run.submit(PlayerAction.at(PlayerAction.Type.CIRCUIT,3,3)).accepted());var after=run.saveState();assertFalse(after.switchOn);assertFalse(EnemyTurns.disabled(after,after.actors.getFirst()));assertFalse(after.circuitPower[0]);}
 @Test void finiteConstructorDoesNotRefillItsMagazine(){var s=room();s.deck=8;var c=EnemyTurns.actor(GameState.ActorKind.CONSTRUCTOR,"constructor",8,6);s.actors.add(c);for(int n=0;n<100;n++){s.tick++;s.actionSerial++;EnemyTurns.advance(s,new ArrayList<>());for(var a:s.actors)if(a.kind==GameState.ActorKind.ROVER){a.hp=0;a.dead=true;}}assertEquals(0,s.constructorStock);assertEquals(6,s.actors.stream().filter(a->a.kind==GameState.ActorKind.ROVER).count());}
 @Test void physicalShutdownDoesNotMagicallyDestroyDeployedMachines(){var s=room();s.deck=8;s.actors.add(EnemyTurns.actor(GameState.ActorKind.CONTROLLER,"control",3,2));s.actors.add(EnemyTurns.actor(GameState.ActorKind.CONSTRUCTOR,"constructor",8,6));s.actors.add(EnemyTurns.actor(GameState.ActorKind.ROVER,"unit",9,6));var run=new RunEngine(s);assertTrue(run.submit(PlayerAction.at(PlayerAction.Type.INTERACT,3,2)).accepted());var after=run.saveState();assertEquals("controller",after.constructorRoute);assertFalse(after.actors.stream().filter(a->a.id.equals("unit")).findFirst().orElseThrow().dead);}
 @Test void pureInformationDoesNotGateDescent(){var s=room();s.playerX=s.hatchX;s.playerY=s.hatchY;s.switchOn=true;var run=new RunEngine(s);assertTrue(Campaign.hatchBlock(s).isEmpty());assertFalse(run.submit(PlayerAction.of(PlayerAction.Type.ADVANCE)).accepted());assertTrue(run.submit(PlayerAction.item(PlayerAction.Type.ADVANCE,"confirm")).accepted());assertEquals(2,run.saveState().deck);}
 @Test void operatingAdjacentMechanismWhileOnHatchDoesNotDepart(){var s=room();s.hatchX=2;s.hatchY=2;s.tiles[2][2]=Tile.HATCH;s.tiles[3][2]=Tile.DOOR_CLOSED;s.switchOn=true;var run=new RunEngine(s);assertTrue(run.submit(PlayerAction.at(PlayerAction.Type.INTERACT,3,2)).accepted());assertEquals(1,run.saveState().deck);assertEquals(Tile.DOOR_OPEN,run.saveState().tiles[3][2]);}
 @Test void endingFollowsWorldOperationsWithoutReadingOrSpeechCompletion(){var s=room();s.deck=10;s.hatchX=2;s.hatchY=2;s.switchX=2;s.switchY=3;s.terminalX=3;s.terminalY=2;s.tiles[2][2]=Tile.HATCH;s.tiles[2][3]=Tile.SWITCH;s.tiles[3][2]=Tile.TERMINAL;var run=new RunEngine(s);assertTrue(run.submit(PlayerAction.at(PlayerAction.Type.INTERACT,2,3)).accepted());assertTrue(run.saveState().flags.contains("enforcement-refused"));assertTrue(run.submit(PlayerAction.at(PlayerAction.Type.INTERACT,3,2)).accepted());assertTrue(run.saveState().flags.contains("broadcast"));assertTrue(run.submit(PlayerAction.item(PlayerAction.Type.ADVANCE,"confirm")).accepted());assertTrue(run.saveState().victory);assertTrue(run.saveState().flags.contains("alice-sacrificed"));assertTrue(Campaign.epilogue(run.saveState()).contains("Destination: Mars"));}
 @Test void noHumanOrPhysicalAliceActorExists(){assertEquals(Set.of("SIRS","ADD","ROVER","CAMERA","TURRET","CONTROLLER","CONSTRUCTOR"),new HashSet<>(Arrays.stream(GameState.ActorKind.values()).map(Enum::name).toList()));}
 @Test void conversationRequiresActualKnowledgeAndPersistsCompletion(){var s=room();s.tick=20;s.radioConnected=true;s.playedExchanges.add("contact");s.knowledge.add("ethics");s.aliceKnowledge.add("ethics");assertFalse(ConversationCatalog.next(s,89_000,2).equals("archive"));assertEquals("archive",ConversationCatalog.next(s,180_000,2));var run=new RunEngine(s);long rng=s.combatRng;assertTrue(run.submit(PlayerAction.item(PlayerAction.Type.EXCHANGE,"archive")).accepted());assertTrue(run.submit(PlayerAction.item(PlayerAction.Type.EXCHANGE,"complete:archive:0")).accepted());assertTrue(run.saveState().completedSpeech.contains("archive:0"));assertEquals(rng,run.saveState().combatRng);assertEquals(20,run.saveState().tick);assertFalse(run.submit(PlayerAction.item(PlayerAction.Type.EXCHANGE,"archive")).accepted());}
 @Test void unseenMechanismChangesDoNotRewriteObservation(){var s=room();s.visible[8][2]=false;s.rememberedTiles[8][2]=Tile.DOOR_CLOSED;s.tiles[8][2]=Tile.DOOR_OPEN;assertEquals(Tile.DOOR_CLOSED,StationSystems.knownTile(s,8,2));}
 @Test void serviceChartNeverReplacesMoreRecentObservations(){var s=room();s.visible[4][3]=false;s.rememberedTiles[4][3]=Tile.DOOR_OPEN;s.blueprintTiles[4][3]=Tile.DOOR_CLOSED;StationSystems.copyServicePlan(s);assertEquals(Tile.DOOR_OPEN,s.rememberedTiles[4][3]);assertTrue(s.knowledge.contains("service-plan-d1"));}
 @Test void eightPaidActionsCannotBeReplacedByOneLongCommitment(){var s=room();s.radioConnected=true;s.playedExchanges.add("contact");s.knowledge.add("ethics");s.aliceKnowledge.add("ethics");s.actionSerial=10;s.lastExchangeActionSerial=7;s.tick=300;assertEquals("",ConversationCatalog.next(s,500_000,2));var run=new RunEngine(s);assertFalse(run.submit(PlayerAction.item(PlayerAction.Type.EXCHANGE,"archive")).accepted());}
 @Test void finalSpeechCanFinishAfterPodOccupancy(){var s=room();s.victory=true;s.playedExchanges.add("farewell");var run=new RunEngine(s);assertTrue(run.submit(PlayerAction.item(PlayerAction.Type.EXCHANGE,"complete:farewell:0")).accepted());assertTrue(run.saveState().completedSpeech.contains("farewell:0"));assertEquals(0,run.saveState().tick);}
 @Test void serviceChartIdentifiesFixedPanelWithoutRevealingLiveStatus(){var s=room();s.fixtures.add(new GameState.Fixture("controller",8,2,0));s.visible[8][2]=false;s.actors.add(EnemyTurns.actor(GameState.ActorKind.CONTROLLER,"supervisor",8,2));StationSystems.copyServicePlan(s);assertTrue(s.knowledge.contains("supervisor-chart:8:2"));assertFalse(s.visible[8][2]);assertEquals(Tile.FLOOR,s.rememberedTiles[8][2]);}
 @Test void forcingLeavesPersistentPhysicalDamageInsteadOfAnIntactDoor(){var s=room();s.tiles[3][2]=Tile.LOCKED_DOOR;var run=new RunEngine(s);assertEquals(4,run.forecast(PlayerAction.at(PlayerAction.Type.FORCE,3,2)).ticks());assertTrue(run.submit(PlayerAction.at(PlayerAction.Type.FORCE,3,2)).accepted());var restored=new RunEngine(run.saveState());assertEquals(Tile.DOOR_OPEN,restored.saveState().tiles[3][2]);assertTrue(restored.saveState().flags.contains("damaged-door:1:3:2"));assertFalse(restored.submit(PlayerAction.at(PlayerAction.Type.INTERACT,3,2)).accepted());assertEquals(4,restored.saveState().tick);}
 @Test void ordinaryDoorPreviewReportsItsActualAcousticCost(){var s=room();s.tiles[3][2]=Tile.DOOR_CLOSED;var run=new RunEngine(s);assertEquals(4,run.forecast(PlayerAction.at(PlayerAction.Type.INTERACT,3,2)).noise());}
 @Test void unpoweredDigitalControllerCannotRedirectButItsManualBreakerWorks(){var s=room();s.deck=8;s.circuitPower[0]=false;s.actors.add(EnemyTurns.actor(GameState.ActorKind.CONTROLLER,"controller",3,2));s.fixtures.add(new GameState.Fixture("controller",3,2,0));var run=new RunEngine(s);assertFalse(run.forecast(PlayerAction.at(PlayerAction.Type.HACK,3,2)).available());assertTrue(run.submit(PlayerAction.at(PlayerAction.Type.CIRCUIT,3,2)).accepted());assertTrue(run.forecast(PlayerAction.at(PlayerAction.Type.HACK,3,2)).available());assertTrue(run.submit(PlayerAction.at(PlayerAction.Type.INTERACT,3,2)).accepted());assertEquals("controller",run.saveState().constructorRoute);}
 @Test void unreachableLastKnownTargetsExpireForEveryMobileMachine(){for(var kind:List.of(GameState.ActorKind.SIRS,GameState.ActorKind.ADD,GameState.ActorKind.ROVER)){var s=room();s.lampOn=false;for(int y=0;y<s.height;y++)s.tiles[5][y]=Tile.WALL;var a=EnemyTurns.actor(kind,"isolated",8,5);a.awareness=GameState.Awareness.INVESTIGATE;a.lastX=2;a.lastY=5;s.actors.add(a);for(int n=0;n<60;n++){s.tick++;s.actionSerial++;EnemyTurns.advance(s,new ArrayList<>());}assertEquals(GameState.Awareness.PATROL,a.awareness,kind.toString());assertTrue(a.x>5);}}
 @Test void transparentProjectileObstructionsDoNotLeaveRangedMachinesHelpless(){var s=room();s.tiles[3][2]=Tile.GLASS;var a=EnemyTurns.actor(GameState.ActorKind.SIRS,"glass",4,2);a.facing=3;s.actors.add(a);for(int n=0;n<2;n++){s.tick++;s.actionSerial++;EnemyTurns.advance(s,new ArrayList<>());}assertTrue(a.x!=4||a.y!=2);assertNotEquals(Tile.GLASS,s.tiles[a.x][a.y]);}
 @Test void aDropWithoutCarryPressureCannotSelectCapacityConversation(){var s=room();s.radioConnected=true;var run=new RunEngine(s);run.submit(PlayerAction.item(PlayerAction.Type.DROP,"gun"));assertFalse(run.saveState().memoryTicks.containsKey("packdrop"));}
 @Test void manualControllerShutdownWorksWithoutCircuitPower(){var s=room();s.deck=8;s.circuitPower[0]=false;s.actors.add(EnemyTurns.actor(GameState.ActorKind.CONTROLLER,"manual",3,2));var run=new RunEngine(s);assertTrue(run.submit(PlayerAction.at(PlayerAction.Type.INTERACT,3,2)).accepted());assertEquals("controller",run.saveState().constructorRoute);}
 @Test void damageWithinLongWorkRetainsItsRealOccurrenceTick(){var s=room();s.tiles[2][3]=Tile.LOCKED_DOOR;var attacker=EnemyTurns.actor(GameState.ActorKind.ADD,"early",5,2);attacker.facing=3;attacker.aiming=true;s.fixtures.add(new GameState.Fixture("light",2,2,0));s.actors.add(attacker);var result=new RunEngine(s).submit(PlayerAction.at(PlayerAction.Type.FORCE,2,3));assertTrue(result.accepted());var gun=result.events().stream().filter(e->e.type().equals("gun")).findFirst().orElseThrow();assertEquals(1,gun.tick());for(var hit:result.events())if(hit.type().equals("hit")&&hit.detail().startsWith("ADD"))assertEquals(gun.tick(),hit.tick());assertTrue(result.events().stream().anyMatch(e->e.type().equals("hit")),"Fixture must exercise actual damage, not merely a shot");}
}
